        local now = tick()
        if now - lastFeedback < FEEDBACK_COOLDOWN then
            pcall(function() fbStatus:SetText(string.format("Maghintay ng %d segundo bago magpadala ulit.", math.ceil(FEEDBACK_COOLDOWN - (now - lastFeedback)))) end)
            return
        end
        local ftype = tostring((Opt.FeedbackType and Opt.FeedbackType.Value) or "Suggestion"):lower()
        local msg = fbTrim((Opt.FeedbackMsg and Opt.FeedbackMsg.Value) or "")
        if msg == "" then pcall(function() fbStatus:SetText("Walang laman ang mensahe.") end); return end
        if #msg > 500 then pcall(function() fbStatus:SetText("Masyadong mahaba ang mensahe (maximum 500 karakter).") end); return end
        local low = msg:lower()
        if low:find("http", 1, true) or low:find("discord.gg", 1, true) or low:find("www.", 1, true) or low:find(".gg/", 1, true) then
            pcall(function() fbStatus:SetText("Bawal ang mga link.") end); return
        end
        pcall(function() fbStatus:SetText("Ipinapadala...") end)
        task.spawn(function()
            local sok, err = sendFeedback(ftype, msg)
            if sok then
                lastFeedback = tick()
                pcall(function() fbStatus:SetText("Naipadala. Salamat!") end)
                pcall(function() Opt.FeedbackMsg:SetValue("") end)
                log("Naipadala ang feedback mo. Salamat!")
            else
                pcall(function() fbStatus:SetText(FB_ERRMAP[err] or ("Nabigong ipadala: " .. tostring(err))) end)
            end
        end)
    end,
})
FG:AddLabel("Maximum 3 mensahe kada oras. Walang link o mention.", true)

freeBuy = Toggles.s_freebuy and Toggles.s_freebuy.Value ~= false
